   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     if(pauseOpen) togglePauseBox(false);
     NET.same='host'; NET.padIx=-1; netPadTick=function(){ return fake; };
